      Lemma fin_exit : forall msF1 mo1 m st ps sz tot spl (r : rv) (F1 : bvmap 5 word) (fc1 : bv 32) (res : Z),
        as_VIS H st msF1 = MS (mkRr r) F1 (Z_to_bv 64 0x10cdc0) fc1 None m (seg_rom asegs) ->
        as_AKREL H st (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        memI m st ps sz tot spl ->
        forall s5v : word, pecore5 r spw (bv_unsigned sp) ff ff s5v -> rgp r = gp -> rtp r = tp -> rs9 r = Z_to_bv 64 res -> frm0 fc1 ->
        vs_temp (ps_vs ps) = vs_temp (ps_vs ps0) -> ps_more ps = ps_more ps0 -> ps_depth ps = ps_depth ps0 ->
        vs_items (ps_vs ps) = vs_items (ps_vs ps0) ->
        0 <= tot <= 0x7ffffffe -> 0 <= res < 2^64 -> exit_sum ps tot res st ->
        as_SR H POST (mkCfg msF1 mo1).
Proof.
