      (* [comment removed for export] *)
      Lemma tail_fail : forall msF1 mo1 m st ps sz tot spl (r : rv) (F1 : bvmap 5 word) (fc1 : bv 32) (c p' : Z),
        as_VIS H st msF1 = MS (mkRr r) F1 (Z_to_bv 64 0xff1bc) fc1 None m (seg_rom asegs) ->
        as_AKREL H st (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        memI m st ps sz tot spl -> psI ps tot -> tot <= 0x7ffffffe -> frm0 fc1 ->
        pecore r spw (bv_unsigned sp) ff c -> rgp r = gp -> rtp r = tp -> ra0 r = a0 ->
        ra1 r = Z_to_bv 64 p' -> q0 <= p' <= e -> bv_unsigned (ra2 r) <> 0 -> 2 <= bv_unsigned (ra3 r) ->
        (rra r = Z_to_bv 64 0x10cdb8 \/ (rra r = Z_to_bv 64 0x10cf88 /\ c = ff)) ->
        pesc_spent H (ps_vs ps0) (e - q0) (lb_bytes (blocks_vs (ps_vs ps))) (as_AL H st0) (as_AL H st) ->
