      Lemma call_utf8 : forall msF1 mo1 m st ps sz tot spl (r : rv) (F1 : bvmap 5 word) (fc1 : bv 32) (c cp : Z)
          (t0w t8w s16 s24 s32 s40 s48 s56 : word) (j16 : list byte),
        as_VIS H st msF1 = MS (mkRr r) F1 (Z_to_bv 64 0x10d694) fc1 None m (seg_rom asegs) ->
        as_AKREL H st (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        memI m st ps sz tot spl ->
        pecore r spw (bv_unsigned sp) ff c -> ra0 r = Z_to_bv 64 (ff + 32) -> ra1 r = Z_to_bv 64 cp -> 0 <= cp <= 1114111 ->
        rra r = Z_to_bv 64 0x10c750 -> 0 <= sz -> sz + 4 <= 256 ->
        peframe m spw t0w t8w s16 s24 s32 s40 s48 s56 ff j16 -> (spl = true -> pespill a0 a2 e isk s16 s24 s32 s40 s48 s56) ->
        (forall msF2 mo2 m2 (r2 : rv) (k : Z),
            as_VIS H st msF2 = MS (mkRr r2) F1 (Z_to_bv 64 0x10c750) fc1 None m2 (seg_rom asegs) ->
            as_AKREL H st (mkCfg msF2 mo2) -> as_MPRES H mo0 mo2 ->
            1 <= k <= 4 -> (cp <= 65535 -> k <= 3) ->
            memI m2 st ps (sz + k) tot spl -> peframe m2 spw t0w t8w s16 s24 s32 s40 s48 s56 ff j16 ->
            pecore r2 spw (bv_unsigned sp) ff c -> rgp r2 = rgp r -> rtp r2 = rtp r -> rs9 r2 = rs9 r ->
            as_SR H POST (mkCfg msF2 mo2)) ->
        as_SR H POST (mkCfg msF1 mo1).
