      (* [comment removed for export] *)
      Lemma call_flush : forall msF1 mo1 m st ps sz tot q spl (r : rv) (F1 : bvmap 5 word) (fc1 : bv 32) (c ret : Z) (s5v : word),
        as_VIS H st msF1 = MS (mkRr r) F1 (Z_to_bv 64 0xf2284) fc1 None m (seg_rom asegs) ->
        as_AKREL H st (mkCfg msF1 mo1) -> as_MPRES H mo0 mo1 ->
        memI m st ps sz (tot + sz) spl -> psI ps tot -> a8I st ps q sz tot ->
        0 < sz <= 256 -> tot + sz <= 0x7ffffffe -> vs_n (ps_vs ps) + tot + sz + (e - q) < 2^26 -> q0 <= q <= e -> frm0 fc1 ->
        pecore5 r spw (bv_unsigned sp) ff c s5v -> rgp r = gp -> rtp r = tp -> ra0 r = a0 -> ra1 r = Z_to_bv 64 (ff + 32) -> ra2 r = Z_to_bv 64 sz ->
        rra r = Z_to_bv 64 ret -> (ret = 0x10b7dc \/ ret = 0x10bad0 \/ ret = 0x10cd78) ->
        (forall msF2 mo2 m2 st2 ps2 (r2 : rv),
            as_VIS H st2 msF2 = MS (mkRr r2) F1 (Z_to_bv 64 ret) fc1 None m2 (seg_rom asegs) ->
            as_AKREL H st2 (mkCfg msF2 mo2) -> as_MPRES H mo0 mo2 ->
            memI m2 st2 ps2 sz (tot + sz) spl -> psI ps2 (tot + sz) -> a8I st2 ps2 q 0 (tot + sz) -> vs_n (ps_vs ps2) = vs_n (ps_vs ps) ->
            pecore5 r2 spw (bv_unsigned sp) ff c s5v -> rgp r2 = gp -> rtp r2 = tp -> rra r2 = Z_to_bv 64 ret -> rs9 r2 = rs9 r ->
            as_SR H POST (mkCfg msF2 mo2)) ->
        as_SR H POST (mkCfg msF1 mo1).
